function solve(input) {
  const cache = new Map();
  const results = [];

  for (const action of input) {
    const { t, op, key } = action;

    if (op === 'put') {
      const { value, ttl } = action;
      cache.set(key, {
        value,
        expiry: t + ttl
      });
    } else if (op === 'get') {
      const entry = cache.get(key);
      if (entry && t < entry.expiry) {
        results.push(entry.value);
      } else {
        if (entry) cache.delete(key);
        results.push(null);
      }
    } else if (op === 'delete') {
      cache.delete(key);
    }
  }

  return results;
}
